            while j < n:
                complement = -nums[i] - nums[j]
                if complement in seen:
                    res.append([nums[i], complement, nums[j]])
                    while j + 1 < n and nums[j] == nums[j + 1]:
                        j += 1
                seen.add(nums[j])
                j += 1
        return res

